tions in the selected window.</p><div class="city-links"><a href="{{ url('/silver-calculator') }}">Calculate a weight ↗</a>@if(config('chandi.marketplace_enabled'))<a href="{{ url('/dealers') }}">Compare dealer profiles ↗</a>@endif<a href="{{ url('/disclaimer') }}">Read the market disclosure ↗</a></div></section>
